    </button>
  );
}
```

# useAppResume (function, `denext/mobile`)

```ts
useAppResume(cb: (awayMs: number) => void): void
```

Hook form of {@linkcode onAppResume}: subscribes on mount, unsubscribes on unmount. The
latest `cb` is always called (it is held in a ref), so passing a fresh closure each render
never re-subscribes.

**Parameters**

- `cb` — Called with awayMs each time the page returns to the foreground. Under 10 s away, probe the connection; 10 s or more, reconnect and refetch.

```tsx
"use client";
import { useAppResume } from "denext/mobile";

export function LiveFeed() {
  useAppResume((awayMs) => (awayMs < 10_000 ? feed.probe() : feed.reconnect()));
  return <Feed />;
}
```

# useBackHandler (function, `denext/mobile`)

```ts
useBackHandler(handler: BackHandler, enabled?: boolean): void
```

Hook form of {@linkcode onBack}: `handler` is registered while the component is mounted and
`enabled` is true, and it always sees the latest props (re-renders do not re-register it, so
its place in the stack stays put). A component mounted later sits above it.

**Parameters**

- `handler` — Returns true to consume the back action.
- `enabled` — Whether to register it (default true).

```tsx
"use client";
import { useBackHandler } from "denext/mobile";

export function Sheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  useBackHandler(() => (onClose(), true), open);
  return open ? <div role="dialog">…</div> : null;
}
```

# useBackProgress (function, `denext/mobile`)

```ts
useBackProgress(): BackGesture | null
```

Hook form of {@linkcode onBackProgress}: the back gesture in flight (`progress` 0…1 and the
`edge` it started from), or `null` when there is none, e.g. to drive a peek of the previous
screen. Always `null` outside the Android shell with `denext mobile add back`.

**Returns** The gesture, or null.

```tsx
"use client";
import { useBackProgress } from "denext/mobile";

export function Page({ children }: { children: unknown }) {
  const gesture = useBackProgress();
  const scale = gesture ? 1 - gesture.progress * 0.08 : 1;
  return <main style={{ transform: `scale(${scale})` }}>{children}</main>;
}
```

# useContextMenu (function, `denext/mobile`)

```ts
useContextMenu(items: ContextMenuItems, onSelect: (id: string) => void, options?: ContextMenuTargetOptions): (el: ContextMenuElement | null) => void
```

{@linkcode attachContextMenu} as a hook: returns a ref callback for the element. The latest
`items`, `onSelect` and `options` are read when a menu opens, so they can change every render
without rebinding.

**Parameters**

- `items` — The items, or a function that builds them when the menu opens.
- `onSelect` — Called with the chosen item's id.
- `options` — Title, long-press delay, haptic.

**Returns** A ref callback to put on the element.

```tsx
"use client";
import { useContextMenu } from "denext/mobile";

export function MessageRow({ message }: { message: { id: string; text: string } }) {
  const menu = useContextMenu(
    [
      { id: "reply", label: "Reply", systemIcon: "arrowshape.turn.up.left" },
      { id: "copy", label: "Copy", systemIcon: "doc.on.doc" },
      { id: "delete", label: "Delete", systemIcon: "trash", destructive: true },
    ],
    (id) => act(id, message.id),
  );
  return <div ref={menu} style={{ borderRadius: 12 }}>{message.text}</div>;
}
```

